{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "Dynamic SOQL with user input",
      "severity": "Low",
      "file": "TaskSearchController.cls",
      "lines": "5-10",
      "explanation": "The method constructs a SOQL query string by concatenating the escaped user input, which is a best‑practice violation and could be exploited if the escaping is removed or bypassed in future changes.",
      "remediation": "Rewrite the query to use a bind variable or Database.queryWithBinds, e.g. SELECT Id, Subject, Status, ActivityDate FROM Task WHERE Subject LIKE :safeFilter WITH USER_MODE LIMIT 200."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "4-7",
      "explanation": "The query string concatenates the user-provided searchKey directly into the SOQL without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially read data from other objects.",
      "remediation": "Rewrite the query to use a bind variable or escape the input: `String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50';` or use `String.escapeSingleQuotes(searchKey)` before concatenation. This prevents injection while still using USER_MODE for CRUD/FLS enforcement."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Not Enforced",
      "severity": "Medium",
      "file": "InvoiceSearchController.cls",
      "lines": "5-10",
      "explanation": "The method returns Invoice__c records with fields that may not be visible to the user due to field‑level security. Apex runs in system mode and ignores FLS unless explicitly enforced, so users could see data they should not.",
      "remediation": "Enforce FLS by adding WITH SECURITY_ENFORCED to the SOSL query or by filtering the returned records with Security.stripInaccessible(AccessType.READ, records)."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection via Dynamic Query",
      "severity": "Medium",
      "file": "ReportFilterController.cls",
      "lines": "1-20",
      "explanation": "The method concatenates user-supplied field filters directly into a SOQL string without validation or escaping, allowing a malicious user to inject arbitrary SOQL clauses and potentially bypass intended filtering.",
      "remediation": "Replace the dynamic string construction with bind variables or Database.queryWithBinds, and enforce an allow‑list for field names. Escape any literal values with String.escapeSingleQuotes or use a static SOQL query with a WHERE clause built from validated inputs."
    }
  ]
}

