{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Field-Level Security Not Enforced",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-10",
      "explanation": "The method updates the Contact.Phone field without checking field-level security, allowing any user with class access to modify the field regardless of their field permissions.",
      "remediation": "Add a check using Security.stripInaccessible or enforce FLS with @AuraEnabled methods, e.g., if (!Schema.sObjectType.Contact.fields.Phone.isAccessible()) { throw new AuraHandledException('Insufficient field permissions'); } before updating."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "Bypass of Field-Level Security in @AuraEnabled method",
      "severity": "Medium",
      "file": "AccountRatingService.cls",
      "lines": "4-12",
      "explanation": "The method queries and updates the AnnualRevenue field in system mode, ignoring the user’s field‑level permissions. This allows authenticated users who lack read access to AnnualRevenue to see its value and indirectly influence the Rating field.",
      "remediation": "Enforce FLS by adding WITH USER_MODE to the SOQL query, or by using Security.stripInaccessible on the queried record, and validate field permissions before accessing or updating fields."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violation: Task creation without permission check",
      "severity": "Medium",
      "file": "CaseEscalationService.cls",
      "lines": "12-20",
      "explanation": "The method creates a Task record without verifying that the running user has Create permission on Task. The permission set explicitly denies Task creation, yet the code swallows any DmlException, hiding the violation from the caller and allowing unauthorized task creation.",
      "remediation": "Add an FLS check before inserting, e.g., if (Task.isCreateable()) { insert t; } else { /* handle lack of permission */ }. Alternatively, use Security.stripInaccessible or WITH SECURITY_ENFORCED on the DML operation to enforce field-level security automatically."
    }
  ]
}

