{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced in @AuraEnabled method",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "public without sharing class CaseHistoryController",
      "explanation": "The class is declared without sharing, so the SOQL query runs in system mode and ignores record‑level sharing. The method returns all recent Case records, potentially exposing cases that the user should not see.",
      "remediation": "Declare the class with sharing (or inherited sharing) or add WITH USER_MODE to the SOQL query. This ensures the query respects the current user's sharing rules before returning records."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Bypassing Record-Level Sharing",
      "severity": "High",
      "file": "FinancialDashboardController.cls",
      "lines": "1-10",
      "explanation": "The class is declared without sharing, so it ignores record‑level sharing rules. Partner community users who have access to the class via the permission set can call the Aura endpoint and retrieve all Opportunity records, regardless of their own sharing permissions.",
      "remediation": "Declare the class with sharing (e.g., `public with sharing class FinancialDashboardController`) or use inherited sharing. Additionally, enforce sharing in the query with `WITH SECURITY_ENFORCED` or remove the class from the partner permission set if it should not be exposed."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing not enforced in Aura-enabled method",
      "severity": "Medium",
      "file": "DataAggregator.cls",
      "lines": "1-20",
      "explanation": "The class is declared without sharing, so the @AuraEnabled method runs in system mode and ignores record‑level sharing. Users with the permission set can query all Leads, including those they should not see, even though FLS is enforced with USER_MODE.",
      "remediation": "Declare the class (or the method) with 'with sharing', or use 'WITH SECURITY_ENFORCED' in the SOQL query to enforce sharing. Remove unused helper or ensure it is called."
    }
  ]
}

