{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Permission Set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, giving support agents org‑wide read/write access that exceeds the intended scope of tier‑1 support. This allows them to view or modify any record in the org, which is a privilege escalation.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary object permissions (e.g., Case read/edit) and consider removing AuthorApex unless required for Apex execution. Ensure the permission set follows least privilege principles."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permission: ManageInternalUsers",
      "severity": "High",
      "file": "Accounts_Payable_Clerk.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ManageInternalUsers system permission, which allows users to manage internal users and potentially alter org-wide settings. This permission is unnecessary for invoice approval and provides excessive privileges.",
      "remediation": "Remove the <userPermissions> entry for ManageInternalUsers from the permission set so that accounts payable clerks only have the permissions required for invoice review and approval."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive ViewAllData permission",
      "severity": "High",
      "file": "Report_Viewer_Plus.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants the ViewAllData system permission, which allows users to read all records in the org regardless of object or field permissions. This exceeds the intended purpose of a report viewer and provides org‑wide read access to sensitive data.",
      "remediation": "Remove the ViewAllData permission from the permission set. Grant only the necessary object permissions (e.g., read on Report) and the RunReports/ExportReport user permissions. If broader access is required, consider creating a separate, more privileged permission set for administrators only."
    }
  ]
}

